INSERT INTO Language_ko_KR (Tag, Text) VALUES
('TXT_KEY_UNIT_BARBARIAN_PIRATE', '코르세르 해적'),
('TXT_KEY_CIV5_BARBARIAN_PIRATE_TEXT', '코르세르 해적은 해상 근접 공격 유닛입니다.[NEWLINE][NEWLINE]바르바리 해적단은 때때로 바르바리 코르세르 또는 오스만 코르세르라고 불리며, 북아프리카에서 활동한 해적이자 사략선으로, 주로 세일, 라바트, 알제, 튀니스, 트리폴리 등의 항구를 거점으로 활동했습니다. 이 지역은 유럽에서는 바르바리 해안으로 알려져 있었는데, 이는 그곳에 거주하는 베르베르족의 이름에서 유래한 용어입니다. 그들의 포식 활동은 지중해 전역으로 확대되었고, 남쪽으로는 서아프리카 대서양 연안과 남아메리카, 그리고 북대서양의 북쪽으로는 아이슬란드까지 이르렀지만, 그들은 주로 서부 지중해에서 활동했습니다. 그들은 선박을 나포하는 것 외에도 약탈도 했으며, 주로 이탈리아, 프랑스, 스페인, 포르투갈의 유럽 해안 도시와 마을을 습격했지만 영국 제도, 네덜란드, 멀리 아이슬란드까지도 습격했습니다. 공격의 주요 목적은 오스만 제국의 노예 무역과 북아프리카 및 중동의 일반적인 무슬림 노예 시장을 위해 기독교 노예를 잡는 것이었습니다.[NEWLINE][NEWLINE]이런 습격은 무슬림이 이베리아를 정복한 직후부터 발생했지만, 바르바리 해적과 바르바리 코르세르라는 용어는 일반적으로 노예상인의 공격 빈도와 범위가 증가한 16세기 이후부터 활동한 습격자에게 적용됩니다. 그 기간 동안 알제, 튀니스, 트리폴리는 오스만 제국의 주권 하에 놓이게 되었는데, 직접 통치되는 지방이나 바르바리 국가로 알려진 자치 속령으로 존재했습니다. 비슷한 습격이 모로코의 세일과 다른 항구에서도 이루어졌습니다.[NEWLINE][NEWLINE]코르세르는 수천 척의 배를 나포하고 해안 마을을 반복적으로 약탈했습니다. 그 결과, 주민들은 스페인과 이탈리아의 긴 해안에 위치한 이전 마을을 버렸습니다. 해안 정착촌에서는 습격이 큰 문제였기 때문에 19세기까지는 습격이 거의 일어나지 않았습니다. 1580년에서 1680년 사이에 코르세르는 약 85만 명의 사람들을 노예로 사로잡았고, 1530년에서 1780년 사이에는 무려 125만 명의 사람들을 노예로 삼았습니다. 일부 코르세르는 유럽에서 추방당한 사람과 개종한 사람으로, 대표적으로 존 워드와 지멘 댄스커가 그렇습니다. 16세기 초에 오스만 제국을 대신하여 알제를 통치했던 터키의 바르바로사 형제인 하이레딘 바르바로사와 오루츠 레이스 역시 악명 높은 코르세르였습니다. 1600년경 유럽 해적들은 바르바리 해안에 진보된 항해 및 조선 기술을 가져왔고, 이를 통해 코르세르는 대서양까지 활동을 확대할 수 있었습니다. 바르바리 습격의 영향은 17세기 초중반에 가장 극심했습니다.[NEWLINE][NEWLINE]17세기 후반에 들어서면서 더욱 강력해진 유럽의 해군이 바르바리 국가들에게 평화 협정을 맺고 그들의 선박에 대한 공격을 중단하도록 압력을 가하면서 코르세르의 활동 범위는 줄어들기 시작했습니다. 그러나 그러한 효과적인 보호 장치가 없는 기독교 국가의 선박과 해안은 19세기 초까지 계속 고통을 겪었습니다. 나폴레옹 전쟁과 1814년~1815년의 빈 회의 이후, 유럽 열강은 바르바리 코르세르를 완전히 진압해야 한다는 데 합의했고, 그 위협은 대부분 억제되었습니다. 미국과 바르바리 국가 사이에 두 차례의 바르바리 전쟁이 일어나는 등 간헐적인 사건이 발생했지만, 결국 1830년 프랑스가 알제를 정복하면서 전쟁은 종식되었습니다.'),
('TXT_KEY_UNIT_BARBARIAN_PIRATE_STRATEGY', '코르세르 해적을 이용해 가까운 바다와 먼 바다에 공포와 불안을 퍼뜨리세요.'),
('TXT_KEY_UNIT_BARBARIAN_PIRATE_HELP', '공해상의 해적 행위에 특화된 빠른 해상 근접 공격 유닛입니다.'),
('TXT_KEY_PIRATE_X', '토르투가'),
('TXT_KEY_PIRATE', '[COLOR_POSITIVE_TEXT]통제구역(ZOC)[ENDCOLOR]을 무시합니다.[NEWLINE]시야가 +1 증가합니다.');